CREATE FUNCTION calculate_age(birth_date DATE)
RETURNS INT
BEGIN
  RETURN TIMESTAMPDIFF(YEAR, birth_date, CURDATE());
END;

SELECT name, calculate_age(birth_date) as age FROM users;

CREATE FUNCTION fibonacci(n INT)
RETURNS INT
BEGIN
  DECLARE a INT DEFAULT 0;
  DECLARE b INT DEFAULT 1;
  DECLARE i INT DEFAULT 0;
  DECLARE temp INT;

  WHILE i < n DO
    SET temp = a + b;
    SET a = b;
    SET b = temp;
    SET i = i + 1;
  END WHILE;

  RETURN a;
END;

CREATE FUNCTION is_palindrome(str VARCHAR(255))
RETURNS BOOLEAN
BEGIN
  RETURN str = REVERSE(str);
END;

SELECT is_palindrome('racecar') as result;

CREATE FUNCTION factorial(n INT)
RETURNS INT
BEGIN
  IF n <= 1 THEN RETURN 1;
  END IF;
  RETURN n * factorial(n - 1);
END;

SELECT factorial(5) as result;

CREATE FUNCTION count_words(text VARCHAR(1000))
RETURNS INT
BEGIN
  DECLARE count INT DEFAULT 0;
  DECLARE pos INT DEFAULT 1;

  WHILE pos <= LENGTH(text) DO
    IF SUBSTRING(text, pos, 1) = ' ' THEN
      SET count = count + 1;
    END IF;
    SET pos = pos + 1;
  END WHILE;

  RETURN count + 1;
END;

