CREATE FUNCTION mask_email(email VARCHAR(255))
RETURNS VARCHAR(255)
BEGIN
  DECLARE at_pos INT;
  DECLARE username VARCHAR(255);
  DECLARE domain VARCHAR(255);

  SET at_pos = POSITION('@' IN email);
  IF at_pos <= 1 THEN RETURN email;
  END IF;

  SET username = SUBSTRING(email, 1, at_pos - 1);
  SET domain = SUBSTRING(email, at_pos);

  RETURN CONCAT(LEFT(username, 1), '***', domain);
END;

SELECT mask_email('user@example.com');

CREATE FUNCTION abs_diff(a INT, b INT)
RETURNS INT
BEGIN
  RETURN ABS(a - b);
END;

SELECT abs_diff(5, 10) as result;

CREATE FUNCTION generate_slug(title VARCHAR(255))
RETURNS VARCHAR(255)
BEGIN
  DECLARE slug VARCHAR(255);
  SET slug = LOWER(title);
  SET slug = REGEXP_REPLACE(slug, '[^a-z0-9]+', '-');
  SET slug = REGEXP_REPLACE(slug, '^-|-$', '');
  RETURN slug;
END;

SELECT generate_slug('Hello World! How are you?') as slug;

CREATE FUNCTION format_number(num INT)
RETURNS VARCHAR(50)
BEGIN
  RETURN FORMAT(num, 0);
END;

SELECT format_number(1234567) as formatted;

CREATE FUNCTION calculate_bmi(weight DECIMAL(5,2), height DECIMAL(5,2))
RETURNS VARCHAR(20)
BEGIN
  DECLARE bmi DECIMAL(5,2);
  SET bmi = weight / (height * height);

  RETURN CASE
    WHEN bmi < 18.5 THEN 'Underweight'
    WHEN bmi < 25 THEN 'Normal'
    WHEN bmi < 30 THEN 'Overweight'
    ELSE 'Obese'
  END;
END;

SELECT calculate_bmi(70, 1.75) as bmi_category;

CREATE FUNCTION truncate_text(text VARCHAR(1000), max_len INT)
RETURNS VARCHAR(1003)
BEGIN
  IF LENGTH(text) <= max_len THEN
    RETURN text;
  END IF;
  RETURN CONCAT(LEFT(text, max_len), '...');
END;

SELECT truncate_text('This is a very long text that needs to be shortened', 20) as truncated;
